// Hand-written `@trpc/server` stub for the flowatlas fixture suite.
//
// Unlike the other fixtures' stubs, this one carries the inference the
// library does: a procedure keeps the input its schema declares and the
// answer its resolver returns, and a router keeps its members, so a client
// typed `createTRPCClient<AppRouter>` is typed from the tree itself (P256).
// Nothing here is a class; `initTRPC.create()` hands back the root object
// whose members a repository re-exports under its own names.
//
// It declares less than the library: no context, no output validation, no
// transformers. It declares nothing of a different kind.

export interface Schema<Output> {
  readonly _output: Output;
}

export interface QueryProcedure<Input, Output> {
  readonly _procedure: 'query';
  readonly _input: Input;
  readonly _answer: Output;
}

export interface MutationProcedure<Input, Output> {
  readonly _procedure: 'mutation';
  readonly _input: Input;
  readonly _answer: Output;
}

export interface Router<Record> {
  readonly _router: true;
  readonly _record: Record;
}

export type AnyRouter = Router<any>;

export interface Middleware {
  readonly _middleware: true;
}

export interface ProcedureBuilder<Input> {
  input<S extends Schema<unknown>>(schema: S): ProcedureBuilder<S['_output']>;
  use(middleware: Middleware | ((opts: { ctx: unknown; next: () => unknown }) => unknown)): ProcedureBuilder<Input>;
  query<R>(resolver: (opts: { ctx: unknown; input: Input }) => R): QueryProcedure<Input, Awaited<R>>;
  mutation<R>(resolver: (opts: { ctx: unknown; input: Input }) => R): MutationProcedure<Input, Awaited<R>>;
}

export interface TRPCRoot {
  router<R extends Record<string, unknown>>(shape: R): Router<R>;
  middleware(fn: (opts: { ctx: unknown; next: () => unknown }) => unknown): Middleware;
  readonly procedure: ProcedureBuilder<void>;
}

export interface TRPCInit {
  create(options?: { transformer?: unknown }): TRPCRoot;
}

export declare const initTRPC: TRPCInit;
